static u_int ahd_resolve_seqaddr ( struct ahd_softc * ahd , u_int address ) { const struct patch * cur_patch ; int address_offset ; u_int skip_addr ; u_int i ; address_offset = 0 ; cur_patch = patches ; skip_addr = 0 ; for ( i = 0 ; i < address ; ) { if ( skip_addr > i ) { int end_addr ; end_addr = min ( address , skip_addr ) ; address_offset += end_addr - i ; i = skip_addr ; } else { i ++ ; } } return ( address - address_offset ) ; } 